CREATE OR REPLACE FUNCTION public.handle_signup() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE chosen public.app_role; areas text[]; mats text[]; BEGIN chosen := CASE NEW.raw_user_meta_data->>'account_type' WHEN 'supplier' THEN 'supplier'::public.app_role WHEN 'recycling' THEN 'recycling'::public.app_role ELSE 'buyer'::public.app_role END; INSERT INTO public.profiles(id,full_name,phone,city) VALUES(NEW.id,coalesce(nullif(trim(NEW.raw_user_meta_data->>'full_name'),''),'Account'),coalesce(NEW.raw_user_meta_data->>'phone',''),coalesce(NEW.raw_user_meta_data->>'city','')); INSERT INTO public.user_roles(user_id,role) VALUES(NEW.id,chosen); INSERT INTO public.business_profiles(user_id,business_name,business_type) VALUES(NEW.id,coalesce(nullif(trim(NEW.raw_user_meta_data->>'business_name'),''),'Business'),coalesce(NEW.raw_user_meta_data->>'business_type','')); IF chosen='supplier' THEN INSERT INTO public.supplier_profiles(user_id,company_name,city,description) VALUES(NEW.id,coalesce(nullif(trim(NEW.raw_user_meta_data->>'business_name'),''),'Company'),coalesce(NEW.raw_user_meta_data->>'city',''),coalesce(NEW.raw_user_meta_data->>'description','')); END IF; IF chosen='recycling' THEN SELECT coalesce(array_agg(v), '{}') INTO areas FROM jsonb_array_elements_text(coalesce(NEW.raw_user_meta_data->'operating_cities','[]'::jsonb)) v WHERE length(v) BETWEEN 1 AND 100; SELECT coalesce(array_agg(v), '{}') INTO mats FROM jsonb_array_elements_text(coalesce(NEW.raw_user_meta_data->'accepted_materials','[]'::jsonb)) v WHERE v IN ('paper','cardboard','aluminum'); INSERT INTO public.recycling_partners(user_id,company_name,approved,operating_areas,accepted_materials) VALUES(NEW.id,coalesce(nullif(trim(NEW.raw_user_meta_data->>'business_name'),''),'Company'),false,areas,mats); END IF; RETURN NEW; END $$;